// Static asset module declarations for TypeScript.
// Kept separate from expo-env.d.ts because Expo regenerates that file.
declare module "*.png" {
  const value: number;
  export default value;
}
declare module "*.jpg" {
  const value: number;
  export default value;
}
declare module "*.jpeg" {
  const value: number;
  export default value;
}
declare module "*.gif" {
  const value: number;
  export default value;
}
declare module "*.webp" {
  const value: number;
  export default value;
}
declare module "*.svg" {
  const value: number;
  export default value;
}
